function ico(n,s=17){return `<svg xmlns="http://www.w3.org/2000/svg" width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.info}</svg>`}
function e(t){return String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const media=(file,cls='landscape',extra='')=>file?`<div class="media ${cls}"><img src="${/^(blob:|data:)/.test(file)?e(file):`media/${e(file)}`}" alt="仅用于原型展示的参考画面模板" loading="lazy"><span class="ribbon">演示素材 · 模板</span>${extra}</div>`:`<div class="placeholder">${ico('image',22)}<b>尚无实际素材</b><small>可生成 / 上传 / 从资产库选择</small></div>`;
const status=(name,kind='gray')=>`<span class="badge ${kind}">${e(name)}</span>`;
const button=(label,action,kind='',extra='')=>`<button class="btn ${kind}" data-action="${e(action)}" ${extra}>${label}</button>`;
